def validate(sources, reporting, prior):
    if set(sources) != set(SCHEMAS):
        raise EvidenceError("Exactly one ledger, budget and revenue source is required")
    if prior >= reporting:
        raise EvidenceError("Prior business date must precede reporting date")
    seen = set()
    for role, rows in sources.items():
        version_keys = defaultdict(set)
        for row in rows:
            context = f"{role} row {row['source_row']}"
            required = set(SCHEMAS[role]) - {"amount", "currency"}
            if any(not row[field] for field in required):
                raise EvidenceError(f"{context}: missing required evidence")
            if role != "revenue" or row["metric"] in MONEY_METRICS:
                if row["currency"] != "USD":
                    raise EvidenceError(f"{context}: expected USD; conversion is not authorized")
            if role == "transactions":
                key = row["transaction_id"]
                if key in seen:
                    raise EvidenceError(f"{context}: duplicate transaction ID {key}")
                seen.add(key)
                iso_date(row["date"], context)
                if row["status"] not in {"posted", "pending", "disputed"}:
                    raise EvidenceError(f"{context}: unsupported transaction status")
                if row["amount_status"] == "unknown":
                    if row["amount"] or row["status"] == "posted":
                        raise EvidenceError(f"{context}: unknown amounts must be blank and pending/disputed")
                elif row["amount_status"] == "confirmed":
                    row["amount"] = format(monetary(row["amount"], context), ".2f")
                else:
                    raise EvidenceError(f"{context}: unsupported amount_status")
                version_keys["ledger"].add(row["source_version"])
            elif role == "budget":
                if not re.fullmatch(r"\d{4}-\d{2}", row["period"]):
                    raise EvidenceError(f"{context}: expected YYYY-MM budget period")
                iso_date(row["period"] + "-01", context)
                key = (row["period"], row["category"], row["currency"])
                if key in seen:
                    raise EvidenceError(f"{context}: duplicate budget key {key}")
                seen.add(key)
                amount = monetary(row["budget_amount"], context)
                if amount < 0:
                    raise EvidenceError(f"{context}: negative budget baseline needs source-owner clarification")
                row["budget_amount"] = format(amount, ".2f")
                version_keys[row["period"]].add(row["source_version"])
            else:
                iso_date(row["date"], context)
                key = (row["date"], row["source"], row["metric"])
                if key in seen:
                    raise EvidenceError(f"{context}: duplicate revenue metric key {key}")
                seen.add(key)
                if row["metric"] in MONEY_METRICS:
                    row["value"] = format(monetary(row["value"], context), ".2f")
                elif row["metric"] in COUNT_METRICS:
                    value = number(row["value"], context)
                    if row["currency"] or value < 0 or value != value.to_integral_value():
                        raise EvidenceError(f"{context}: expected a nonnegative count with blank currency")
                    row["value"] = str(int(value))
                else:
                    raise EvidenceError(f"{context}: unknown metric meaning; clarify with Finance")
                version_keys[(row["date"], row["source"])].add(row["source_version"])
        if any(len(versions) != 1 for versions in version_keys.values()):
            raise EvidenceError(f"{role}: conflicting source versions within a population")
    for day in (reporting, prior):
        if not any(r["date"] == day.isoformat() for r in sources["transactions"]):
            raise EvidenceError(f"Ledger has no evidence for {day}; do not infer zero activity")


def money(value):
    return f"{value:+.2f} USD"


def variance(actual, baseline):
    if baseline < 0:
        raise EvidenceError("Negative comparison baseline: clarify percentage denominator before concluding materiality")
    delta = actual - baseline
    material = abs(delta) > Decimal("500") and abs(delta) > baseline * Decimal("0.10")
    percent = "unavailable (zero baseline)" if baseline == 0 else f"{delta / baseline * 100:+.2f}%"
    return delta, percent, material


def cell(value):
    return str(value).replace("|", "\\|").replace("\n", " ").replace("\r", " ")


def table(headers, rows):
# Financial interpretation and handoff

Authority: DESIGN.md and interviews/interview-6.md. The initial request is August 11, 2026 versus August 10 for the August 12 operations meeting; current monthly targets are August 2026. Future runs take manager-specified dates.

## Status and amount

Daily figures include only the date named in their label. Sum signed confirmed amounts separately for posted, pending and disputed rows; never combine them into a cash total. Reporting-date posted minus prior-business-date posted is the daily change. Preserve negative posted credits/corrections and genuine numeric zeros.

Transaction status and amount state are distinct. An explicitly unknown amount is blank, retained and excluded from totals; only pending/disputed transactions may have this state. A posted amount must be confirmed. Keep all pending/disputed rows from month start through reporting date in the unresolved queue, including unknown amounts and earlier dates.

## Budget reconciliation

For every category, actual is the sum of signed posted ledger amounts from month start through reporting date. Match the applicable budget by period, category and USD currency. Variance = actual minus numeric full monthly target; do not prorate. Display all current budget categories, including no observed posted activity, and all posted categories, including unmapped categories. An absent budget is unavailable, never an invented zero. Preserve owner and review_rule; review_rule adds context and does not override materiality.

## Snapshots and materiality

Match revenue snapshots by source and metric for the reporting date and specified prior business date. Compare collected_revenue, outstanding_balance and payment_plan_balance separately. Preserve enrolled_students and past_due_accounts as nonmonetary counts; no USD threshold applies to those counts. Never sum payment-plan and outstanding balances or infer a ledger/snapshot accounting identity that the manager has not supplied.

For a known nonnegative baseline, signed variance = actual minus baseline. Materiality requires both abs(variance) > 10% × baseline and abs(variance) > USD 500. Equality at either threshold is not material. Preserve an exact signed monetary variance for zero baselines; percentage is unavailable, and only abs(variance) > USD 500 qualifies. Round displayed percentages only; do not round monetary calculations or threshold decisions.

Interview-6 confirms that materiality applies regardless of baseline sign, but does not specify the percentage denominator or whether ten percent of a negative baseline uses its signed value or magnitude. The executable stops and requests clarification if a negative comparison baseline arises; it does not silently apply abs(baseline). Negative transaction credits still participate in daily and month-to-date totals. All monetary sources and thresholds must be USD; foreign exchange conversion is outside this workflow.

## Missing evidence and responsibilities

Unmapped posted categories are labeled and escalated; missing revenue comparators remain unresolved and never zero-filled. Interview-6 explicitly permits a draft when current-month budget evidence is missing: preserve independently supported transaction totals and open items, withhold unsupported budget variances and ask Finance to supply the baselines. Even if the valid budget source contains no current-month rows, supported sections remain available with explicit gaps. Invalid/ambiguous amounts, conflicting versions, duplicates and unavailable or invalid entire source populations prevent usable output.

Operations owns ledger clarification. Finance owns budget and revenue clarification. Budget row owners provide category context; they do not replace source ownership. The Operations Owner reviews the draft and decides spending, escalation and dispute resolution. The command documents clarification requests; it does not send messages or take decisions.

A fresh full-tab fetch verifies retrieval coverage, not the completeness of the business population. The sources currently have no explicit completeness certification or freshness rule. Every draft carries that unresolved review item, with observed coverage and business versions so the source owners can confirm them. Do not claim a financial trend or forecast solely from a daily change or month-to-date underspend against a full monthly target.

